We’ve hit a wall with shell regex in zsh and heavy grep stalls. But we already have the goldmine: **flywheel_intel.txt** contains remote URLs and GitHub descriptions for every repo. Now we just need the **directory structure and ecosystem markers** for a finer-grained map. Python to the rescue—it’s installed and regex‑safe.

Run this Python script; it’ll produce a clean `final_intel.json` with everything we need to build the **definitive, multi‑layered categorization**:

```bash
cd ~/refTemplates
cat > recon.py <<'PYEOF'
import os, json, subprocess, re

def get_remote(repo_path):
    try:
        out = subprocess.check_output(['git', '-C', repo_path, 'remote', 'get-url', 'origin'], text=True)
        return out.strip()
    except:
        return 'NO_REMOTE'

def get_readme_info(repo_path):
    for fname in ['README.md','README.rst','README']:
        fpath = os.path.join(repo_path, fname)
        if os.path.isfile(fpath):
            with open(fpath, 'r', errors='ignore') as f:
                content = f.read()
            lines = content.splitlines()
            headers = [l.strip() for l in lines if l.startswith('#')]
            toc = 'table of contents' in content.lower()
            return {
                'file': fname,
                'lines': len(lines),
                'first_20': lines[:20],
                'headers': headers[:30],
                'toc': toc
            }
    return None

def get_ecosystem(repo_path):
    eco = []
    if os.path.isfile(os.path.join(repo_path, 'Cargo.toml')): eco.append('Rust')
    if os.path.isfile(os.path.join(repo_path, 'package.json')): eco.append('Node.js')
    if os.path.isfile(os.path.join(repo_path, 'go.mod')): eco.append('Go')
    if os.path.isfile(os.path.join(repo_path, 'setup.py')) or os.path.isfile(os.path.join(repo_path, 'pyproject.toml')): eco.append('Python')
    return eco

def get_top_files_dirs(repo_path):
    try:
        entries = os.listdir(repo_path)
        dirs = [d+'/' for d in entries if os.path.isdir(os.path.join(repo_path,d))]
        files = [f for f in entries if os.path.isfile(os.path.join(repo_path,f))]
        return {'dirs': dirs[:30], 'files': files[:30]}
    except:
        return {'dirs':[], 'files':[]}

def extract_github_owner_repo(remote):
    # patterns: https://github.com/user/repo.git or git@github.com:user/repo.git
    m = re.search(r'github\.com[:/]([^/]+)/([^/]+?)(\.git)?$', remote)
    if m:
        return f'{m.group(1)}/{m.group(2)}'
    return None

root = os.getcwd()
data = {}
for entry in sorted(os.listdir(root)):
    path = os.path.join(root, entry)
    if os.path.isdir(path) and os.path.isdir(os.path.join(path, '.git')):
        remote = get_remote(path)
        readme = get_readme_info(path)
        eco = get_ecosystem(path)
        top = get_top_files_dirs(path)
        github = extract_github_owner_repo(remote)
        data[entry] = {
            'remote': remote,
            'github': github,
            'readme': readme,
            'ecosystem': eco,
            'top_files': top['files'],
            'top_dirs': top['dirs']
        }
    elif os.path.isfile(path):
        # plain file
        try:
            with open(path, 'rb') as f:
                head = f.read(200)
            kind = subprocess.check_output(['file', '-b', path], text=True).strip()
        except:
            kind = 'unknown'
        data[entry] = {'type': 'file', 'file_cmd': kind}

with open('final_intel.json', 'w') as f:
    json.dump(data, f, indent=2)
print("final_intel.json written.")
PYEOF
python3 recon.py
cat final_intel.json
```

This will dump a complete, structured JSON of every repo’s remote, README headers, ecosystem, top-level files/dirs. Paste it back and I will:

- Map each repo to the **exact subsystem** it belongs to in your Flywheel build
- Produce a **multi‑level category tree** with justification
- Generate the final `organize.sh` and `revert.sh` scripts

Zero guesswork—100% based on the actual code and descriptions you already collected.
